// TS_Demux_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module TS_Demux_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic  c_enable,
  input logic [3:0] c_pid_en,
  input logic [12:0] c_pid0,
  input logic [12:0] c_pid1,
  input logic [12:0] c_pid2,
  input logic [12:0] c_pid3,
  input logic [31:0] c_ring_base,
  input logic [15:0] c_ring_pkts,
  input logic [15:0] c_rd_idx,
  input logic [15:0] c_wr_idx,
  input logic  c_busy,
  input logic  c_err,
  input logic [15:0] c_pkt_cnt,
  input logic [15:0] c_drop_cnt,
  input logic [15:0] c_cc_err_cnt,
  input logic [15:0] c_ovf_cnt,
  input logic  c_pkt,
  input logic  c_drop,
  input logic  c_cc_err,
  input logic  c_err_irq
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 15;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:14];          // model of every stored word
  logic [3:0] m_set;                // interrupt bits set this clock

  always_comb begin
    m_set = '0;
    if (c_pkt) m_set[0] = 1'b1;
    if (c_drop) m_set[1] = 1'b1;
    if (c_cc_err) m_set[2] = 1'b1;
    if (c_err_irq) m_set[3] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'hF;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h1F;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'h3FFFFFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'h3FFFFFF;
      if (m_wr && m_map && m_idx == 8) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 9) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'hFFFF;
      if (m_wr && m_map && m_idx == 10) m_w[10] <= ((m_w[10] & ~m_be) | (PWDATA & m_be)) & 32'hFFFF;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h7C020100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 0;
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return m_w[10];
      11: return (32'(c_wr_idx) << 0);
      12: return (32'(c_busy) << 0) | (32'(c_err) << 1);
      13: return (32'(c_pkt_cnt) << 0) | (32'(c_drop_cnt) << 16);
      14: return (32'(c_cc_err_cnt) << 0) | (32'(c_ovf_cnt) << 16);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][3:0] & m_w[2][3:0]))
  `SVA_INV(a_core_enable, c_enable == m_w[5][0:0])
  `SVA_INV(a_core_pid_en, c_pid_en == m_w[5][4:1])
  `SVA_INV(a_core_pid0, c_pid0 == m_w[6][12:0])
  `SVA_INV(a_core_pid1, c_pid1 == m_w[6][25:13])
  `SVA_INV(a_core_pid2, c_pid2 == m_w[7][12:0])
  `SVA_INV(a_core_pid3, c_pid3 == m_w[7][25:13])
  `SVA_INV(a_core_ring_base, c_ring_base == m_w[8][31:0])
  `SVA_INV(a_core_ring_pkts, c_ring_pkts == m_w[9][15:0])
  `SVA_INV(a_core_rd_idx, c_rd_idx == m_w[10][15:0])
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_enable == 1'h0 && c_pid_en == 4'h0 && c_pid0 == 13'h0 && c_pid1 == 13'h0 && c_pid2 == 13'h0 && c_pid3 == 13'h0 && c_ring_base == 32'h0 && c_ring_pkts == 16'h0 && c_rd_idx == 16'h0)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CTRL, m_rd && m_map && m_idx == 5)
  `FC(wr_CTRL, m_wr && m_map && m_idx == 5)
  `FC(rd_PID01, m_rd && m_map && m_idx == 6)
  `FC(wr_PID01, m_wr && m_map && m_idx == 6)
  `FC(rd_PID23, m_rd && m_map && m_idx == 7)
  `FC(wr_PID23, m_wr && m_map && m_idx == 7)
  `FC(rd_RING_BASE, m_rd && m_map && m_idx == 8)
  `FC(wr_RING_BASE, m_wr && m_map && m_idx == 8)
  `FC(rd_RING_PKTS, m_rd && m_map && m_idx == 9)
  `FC(wr_RING_PKTS, m_wr && m_map && m_idx == 9)
  `FC(rd_RD_IDX, m_rd && m_map && m_idx == 10)
  `FC(wr_RD_IDX, m_wr && m_map && m_idx == 10)
  `FC(rd_WR_IDX, m_rd && m_map && m_idx == 11)
  `FC(wr_WR_IDX, m_wr && m_map && m_idx == 11)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 12)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 12)
  `FC(rd_PKTS, m_rd && m_map && m_idx == 13)
  `FC(wr_PKTS, m_wr && m_map && m_idx == 13)
  `FC(rd_ERRS, m_rd && m_map && m_idx == 14)
  `FC(wr_ERRS, m_wr && m_map && m_idx == 14)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_PKT_set, m_set[0])
  `FC(irq_PKT_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_PKT_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_PKT_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_DROP_set, m_set[1])
  `FC(irq_DROP_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_DROP_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_DROP_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_CC_ERR_set, m_set[2])
  `FC(irq_CC_ERR_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_CC_ERR_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_CC_ERR_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_ERR_set, m_set[3])
  `FC(irq_ERR_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_ERR_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_ERR_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind TS_Demux_apb TS_Demux_apb_sva u_apb_sva (.*);
